'use strict';
const M=window.RitmModel,$=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽', short=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1,notation:'compact'}).format(n)+' ₽',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}).replace('.','');
let aiProvider='';
let state=M.initial(),period=30,uplift=0,page='pulse',online=false,aiConfigured=false,busy=false,chatMessages=[],operationFilter='',toastTimer,importedCount=0;
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(path.includes('chat')||path.includes('config')?110000:20000)});let data;try{data=await r.json()}catch{throw Error('Сервер вернул неожиданный ответ')};if(!r.ok)throw Error(data.error||'Не удалось выполнить действие');return data}
const post=(path,body={})=>api(path,{method:'POST',body:JSON.stringify(body)});
function saveLocal(){try{localStorage.setItem('ritm-state-v1',JSON.stringify(state))}catch{notify('Изменения доступны до закрытия страницы: хранилище браузера недоступно')}}
async function sync(){if(online)state=await api('/api/state');else saveLocal()}
function available(){return M.available(state)}
const scoreText=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);
function head(eyebrow,title,desc,action='report'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions"><div class="date-chip">${icon('calendar')}27 октября 2026</div>${action==='report'?`<button class="btn secondary" data-action="export">${icon('down')}Скачать отчёт</button>`:action==='expense'?`<button class="btn primary" data-action="expense">${icon('plus')}Добавить расход</button>`:''}</div></div>`}
function periodTabs(){return `<div class="period-tabs" aria-label="Период аналитики">${[7,30,90].map(n=>`<button data-period="${n}" aria-pressed="${period===n}">${n} дней</button>`).join('')}</div>`}
function kpis(d){return `<div class="kpi-grid"><article class="card"><div class="kpi-label">Выручка за ${period} дней${icon('chart')}</div><div class="kpi-value">${money(d.revenue)}</div><div class="kpi-bottom">За вычетом возвратов</div></article><article class="card"><div class="kpi-label">Операционная прибыль${icon('up')}</div><div class="kpi-value">${money(d.profit)}</div><div class="kpi-bottom"><span class="positive">${d.margin.toFixed(1)}% маржа</span> · до налогов</div></article><article class="card"><div class="kpi-label">Средний чек${icon('coffee')}</div><div class="kpi-value">${money(d.average)}</div><div class="kpi-bottom">${d.orders.toLocaleString('ru-RU')} покупок за период</div></article><article class="card"><div class="kpi-label">Расходы за ${period} дней${icon('wallet')}</div><div class="kpi-value">${money(d.expenses)}</div><div class="kpi-bottom">Включая добавленные вручную</div></article></div>`}
function forecastSVG(d){const vals=[available(),...d.forecast.map(p=>p.balance)],W=740,H=255,left=46,right=15,top=25,bottom=32;const min=Math.min(-40000,...vals)-10000,max=Math.max(200000,...vals)+10000;const x=i=>left+i*(W-left-right)/14,y=v=>top+(max-v)*(H-top-bottom)/(max-min);const pts=vals.map((v,i)=>[x(i),y(v)]);const path=pts.map(([a,b],i)=>`${i?'L':'M'}${a.toFixed(1)},${b.toFixed(1)}`).join(' ');const area=path+` L${x(14)},${y(min)} L${x(0)},${y(min)}Z`;let grid='';for(const v of [200000,100000,0,-100000,-200000].filter(v=>v>=min&&v<=max))grid+=`<line x1="${left}" y1="${y(v)}" x2="${W-right}" y2="${y(v)}" stroke="${v===0?'#dadbe1':'#efeff2'}" ${v===0?'stroke-dasharray="4 4"':''}/><text x="${left-9}" y="${y(v)+3}" text-anchor="end">${v/1000} тыс.</text>`;const gapIndex=vals.findIndex(v=>v<0);return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Прогноз остатка на 14 дней. ${d.gap?'Максимальная нехватка '+money(d.gap):'Отрицательного остатка нет'}"><defs><linearGradient id="forecast-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ef3124" stop-opacity=".13"/><stop offset="1" stop-color="#ef3124" stop-opacity=".01"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#forecast-fill)"/><path d="${path}" fill="none" stroke="#ef3124" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(([a,b],i)=>`<circle cx="${a}" cy="${b}" r="${i===0||i===14?4:2.5}" fill="#fff" stroke="#ef3124" stroke-width="1.6"><title>${i?date(M.addDay(i)):'Сегодня'}: ${money(vals[i])}</title></circle>`).join('')}${gapIndex>=0?`<line x1="${x(gapIndex)}" y1="${top}" x2="${x(gapIndex)}" y2="${H-bottom}" stroke="#ef3124" stroke-dasharray="3 4" opacity=".4"/><text x="${Math.min(W-150,x(gapIndex)+8)}" y="${top+12}" text-anchor="start" style="fill:#d43f34;font-size:9px">Риск кассового разрыва</text>`:''}${[0,3,7,10,14].map(i=>`<text x="${x(i)}" y="${H-8}" text-anchor="${i===14?'end':i===0?'start':'middle'}">${i===0?'Сегодня':date(M.addDay(i))}</text>`).join('')}</svg>`}
function paymentRows(limit=4){return state.payments.slice().sort((a,b)=>a.day-b.day).slice(0,limit).map(p=>{const dt=M.addDay(p.day),parts=date(dt).split(' ');return `<div class="payment-row"><div class="payment-date"><strong>${parts[0]}</strong><small>${parts[1]}</small></div><div class="payment-info"><strong>${esc(p.name)}</strong><small>${esc(p.category)}${p.id==='tax'?' · УСН 6%':''}${p.paid?'':` · <button class="payment-edit" data-finance="payment" data-id="${p.id}" aria-label="Изменить ${esc(p.name)}">Изменить</button>`}</small></div><div class="payment-amount">${money(p.amount)}</div>${p.paid?'<span class="tag green">Учтено</span>':`<button class="text-btn" data-pay="${p.id}">Учесть оплату</button>`}</div>`}).join('')}
const advices=[{id:'supply',icon:'wallet',title:'Согласовать график закупок',body:'Обсудите разбивку поставки с поставщиком. Сначала проверьте остатки.',label:'Денежный поток'},{id:'menu',icon:'coffee',title:'Проверить экономику комбо',body:'Рассчитайте маржу кофе с десертом до запуска предложения.',label:'Средний чек'},{id:'reserve',icon:'calendar',title:'Проверить аванс УСН',body:'Проверьте доход за 9 месяцев, вычеты и предыдущие авансы.',label:'Обязательства'}];
function adviceRows(){return advices.map(a=>`<article class="advice-row"><span class="advice-icon">${icon(a.icon)}</span><div class="advice-body"><strong>${a.title}</strong><p>${a.body}</p></div><button class="check-btn" aria-label="${state.done.includes(a.id)?'Вернуть в план':'Отметить выполненным'}: ${a.title}" data-advice="${a.id}" aria-pressed="${state.done.includes(a.id)}">${icon('check')}</button></article>`).join('')}
function pulse(d){return head('Финансовый обзор','Главное<br>на сегодня.','Остаток, ближайшие обязательства и прогноз на 14 дней.')+financeToolbar()+`<div class="hero-grid"><article class="card health-card"><div class="health-label">Индекс здоровья бизнеса<button data-action="score" aria-label="Как рассчитывается индекс">i</button></div><div class="health-center"><div class="score">${scoreText(d.score)}<small> / 100</small></div><svg class="pulse-wave" viewBox="0 0 140 60" fill="none" aria-hidden="true"><path d="M0 33h30l8-11 12 23L67 5l15 49 12-30 8 9h38" stroke="#f45c50" stroke-width="2.8" stroke-linejoin="round" class="wave-path"/></svg></div><div class="health-foot ${d.score>=70&&!d.gap?'good':d.score<40?'critical':''}">${d.score>=70&&!d.gap?'Финансовый запас устойчив':d.gap?'Есть риск нехватки денег':'Проверьте запас денег и маржу'}</div></article><article class="card balance-card"><div class="label">Остаток финансового плана${icon('wallet')}</div><div class="big-money">${money(available())}</div><div class="balance-footer"><span class="status-dot"></span>Текущий остаток<button class="text-btn" data-finance="plan">Изменить</button></div></article><article class="card risk-card"><div><div class="risk-kicker">${icon(d.gap?'alert':'check')}${d.gap?'Заглянем на 14 дней вперёд':'Сценарий без кассового разрыва'}</div><div class="risk-title">${d.gap?`Может не хватить<br><strong>${money(d.gap)}</strong>`:'Обязательства<br><strong>под контролем</strong>'}</div></div><div><p>${d.gap?`${d.gapDate===M.DATE?'Остаток уже ниже нуля.':'Первый риск — '+date(d.gapDate)+'.'} Проверим, что можно изменить уже сейчас.`:'Отрицательного остатка в выбранном сценарии нет. Сохраняйте резерв.'}</p><button class="text-btn" data-ask="Помоги составить план, чтобы избежать кассового разрыва">Составить план${icon('arrow')}</button></div></article></div><div class="section-grid"><article class="card"><div class="card-heading"><div><h2>Деньги на горизонте</h2><p>Прогноз остатка · следующие 14 дней</p></div><button class="text-btn" data-finance="plan">Настроить прогноз${icon('arrow')}</button></div><div class="chart-legend"><span class="legend-line">Прогноз остатка</span><span class="legend-line gray">Ноль — граница риска</span></div><div class="chart-container">${forecastSVG(d)}</div><div class="scenario"><span>Что, если выручка изменится?</span><div class="segmented" aria-label="Сценарий прогноза"><button data-uplift="0" aria-pressed="${uplift===0}">Базовый</button><button data-uplift="15" aria-pressed="${uplift===15}">Выручка +15%</button></div></div></article><article class="card assistant-preview"><div class="assistant-heading"><span class="ai-badge">${icon('spark')}</span>Ритм помогает</div><div class="assistant-intro">Меньше таблиц.<br>Больше понимания.</div><p>Объяснит цифры простыми словами и поможет составить план действий.</p><div class="mini-insight"><strong>${d.gap?(state.payments.some(p=>!p.paid)?'Крупные платежи впереди.':'Проверьте текущий остаток.'):'Сравните два сценария.'}</strong> ${d.gap?(state.payments.some(p=>!p.paid)?'Зарплата, аренда и резерв под налоги влияют на прогноз. Разберём каждый шаг вместе.':'Обязательства отмечены оплаченными. Сверьте остаток и уже учтённые операции. Не нужно оплачивать их повторно.'):'Рост выручки — гипотеза. Решение стоит проверять на марже и фактических продажах.'}</div><button class="btn primary" data-go="assistant">${icon('spark')}Обсудить с помощником${icon('arrow')}</button><div class="small-caption">${aiConfigured?'Помощник подключён':'Подключите помощника в настройках'}</div></article></div>${kpis(d)}<div class="lower-grid"><section><div class="section-title"><h2>Ближайшие платежи</h2><button class="text-btn" data-go="payments">Все обязательства${icon('arrow')}</button></div><div class="card">${paymentRows()}</div></section><section><div class="section-title"><h2>С чего начать</h2><span class="tag">${state.done.length} из 3 выполнено</span></div><div class="card">${adviceRows()}</div></section></div>`}
function barsSVG(d){const W=900,H=250,l=50,t=20,b=30,max=Math.max(1,...d.history.map(h=>h.revenue))*1.15;const step=(W-l-12)/d.history.length;let s='';for(let i=0;i<4;i++){let val=Math.round(max*i/3/1000)*1000;const y=H-b-val/max*(H-t-b);s+=`<line x1="${l}" x2="${W-12}" y1="${y}" y2="${y}" stroke="#eeeef2"/><text x="${l-10}" y="${y+3}" text-anchor="end">${val/1000} тыс.</text>`}s+=d.history.map((h,i)=>{const v=h.revenue-h.refunds,barH=v/max*(H-t-b);return `<rect x="${l+i*step+step*.16}" y="${H-b-barH}" width="${step*.68}" height="${barH}" rx="${Math.min(4,step*.18)}" fill="${i>=d.history.length-7?'#ef3124':'#f5aaa2'}"><title>${date(h.date)} · ${money(v)}</title></rect>`}).join('');const indexes=[0,Math.floor(d.history.length/3),Math.floor(d.history.length*2/3),d.history.length-1];s+=indexes.map(i=>`<text x="${l+i*step+step/2}" y="${H-7}" text-anchor="${i===indexes[3]?'end':'middle'}">${date(d.history[i].date)}</text>`).join('');return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Выручка по дням за ${period} дней">${s}</svg>`}
function avgSVG(d){const W=680,H=210,l=40,b=30,t=20,max=600,pts=d.history.map((h,i)=>[l+i*(W-l-12)/(d.history.length-1),H-b-(h.orders?(h.revenue-h.refunds)/h.orders:0)/max*(H-t-b)]);return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Средний чек по дням">${[0,150,300,450,600].map(v=>`<line x1="${l}" x2="${W-12}" y1="${H-b-v/max*(H-t-b)}" y2="${H-b-v/max*(H-t-b)}" stroke="#eeeef2"/><text x="${l-9}" y="${H-b-v/max*(H-t-b)+3}" text-anchor="end">${v}</text>`).join('')}<path d="${pts.map(([x,y],i)=>`${i?'L':'M'}${x},${y}`).join(' ')}" stroke="#ef3124" fill="none" stroke-width="2.5" stroke-linecap="round"/><text x="${l}" y="${H-7}">${date(d.history[0].date)}</text><text x="${W-12}" y="${H-7}" text-anchor="end">${date(M.DATE)}</text></svg>`}
function categoryTotals(d){return [['Продукты и закупки',Math.round((d.expenses-state.expenses.reduce((n,e)=>n+(e.date>=d.history[0].date?e.amount:0),0))*.43),'#ef3124'],['Команда',Math.round((d.expenses-state.expenses.reduce((n,e)=>n+(e.date>=d.history[0].date?e.amount:0),0))*.27),'#ff9288'],['Аренда',Math.round((d.expenses-state.expenses.reduce((n,e)=>n+(e.date>=d.history[0].date?e.amount:0),0))*.17),'#f6c4bc']].concat([['Прочее',0,'#e7e7ed']]).map((a,i,all)=>i===3?[a[0],d.expenses-all.slice(0,3).reduce((n,e)=>n+e[1],0),a[2]]:a)}
function analytics(d){const cats=categoryTotals(d);return head('Видеть больше, решать точнее','Цифры без догадок.','Выручка, расходы и экономика кофейни в одном месте.')+financeToolbar()+`<div class="toolbar">${periodTabs()}<button class="text-btn" data-action="table">${icon('grid')}По дням в таблице</button></div>${kpis(d)}<div class="analytics-grid"><article class="card wide"><div class="card-heading"><div><h2>Выручка по дням</h2><p>${date(d.history[0].date)} — ${date(M.DATE)} · после возвратов</p></div><span class="tag red">${period} дней</span></div><div class="chart-container">${barsSVG(d)}</div></article><article class="card"><div class="card-heading"><div><h2>Как менялся средний чек</h2><p>Выручка за вычетом возвратов / покупки</p></div></div><div class="chart-container">${avgSVG(d)}</div></article><article class="card"><h2>Структура расходов</h2><p class="small-caption">Плановое распределение</p><div class="donut-layout"><div class="donut"><div><strong>${short(d.expenses)}</strong><small>всего расходов</small></div></div><div class="category-list">${cats.map(([n,v,c])=>`<div class="category-item"><i style="background:${c}"></i>${n}<strong>${short(v)}</strong></div>`).join('')}</div></div></article></div><p class="small-caption">Возвраты за период: ${money(d.refunds)}. Операционная прибыль указана до налогов.</p>`}
function expensesTable(){const rows=state.expenses.filter(e=>(e.name+' '+e.category).toLowerCase().includes(operationFilter.toLowerCase())).slice().reverse();return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Операция</th><th>Категория</th><th>Дата</th><th class="amount">Сумма</th><th aria-label="Действия"></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.name)}</td><td><span class="tag">${esc(e.category)}</span></td><td>${date(e.date)}</td><td class="amount">−${money(e.amount)}</td><td><button class="text-btn" data-business="delete-expense" data-id="${esc(e.id)}" aria-label="Удалить расход ${esc(e.name)}">Удалить</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${operationFilter?'Ничего не найдено':'Дополнительных расходов пока нет. Добавьте первый.'}</div>`}
function payments(){return head('Не держите всё в голове','Деньги любят порядок.','Учитывайте расходы и держите обязательства перед глазами.','expense')+financeToolbar()+`<div class="section-grid"><article class="card"><div class="card-heading"><div><h2>Календарь обязательств</h2><p>Запланированные платежи</p></div>${icon('calendar')}</div>${paymentRows()}<p class="small-caption">Отмечайте уже совершённые оплаты. Деньги через Ритм не переводятся.</p></article><article class="card risk-card"><div><div class="risk-kicker">${icon('wallet')}Финансовая дисциплина</div><div class="risk-title">Планируйте раньше.<br>Дышите спокойнее.</div></div><div><p>${state.payments.find(p=>p.id==='tax')?.paid?'Аванс УСН '+money(M.estimateTax(state.tax||M.defaultTax()).payable)+' учтён в оплатах и уже отражён в остатке.':'Аванс УСН — '+money(M.estimateTax(state.tax||M.defaultTax()).payable)+' до 28 октября. Сверьте расчёт и запланируйте пополнение ЕНС.'}</p><button class="text-btn" data-ask="Как учитывать налоги и не забывать сроки?">Разобрать с помощником${icon('arrow')}</button></div></article></div>${bankPanel()}${taxPanel()}<div class="section-title"><h2>Дополнительные расходы</h2><button class="text-btn" data-action="import">Импорт CSV${icon('arrow')}</button></div><div class="toolbar"><label class="search-wrap">${icon('search')}<input id="expense-search" type="search" placeholder="Найти расход или категорию" aria-label="Поиск расходов" value="${esc(operationFilter)}"></label><button class="btn secondary" data-action="export">${icon('down')}Отчёт CSV</button></div><div class="card" id="expense-table">${expensesTable()}</div>`}
function messageHTML(m){return `<div class="message ${m.role==='user'?'user':''}">${m.role==='user'?'':`<span class="ai-badge">${icon('spark')}</span>`}<div><div class="message-content">${esc(m.content)}</div>${m.role==='assistant'?`<div class="message-mode">${m.mode==='chatgpt'?'Ответ ChatGPT · используется ваш план':m.mode==='ollama'?'Ответ локальной модели Ollama':m.mode==='ai'?'Ответ подключённой модели':m.mode==='error'?'Ошибка подключения':'Разбор по правилам · без языковой модели'}</div>`:''}</div></div>`}
function assistant(d){return head('Вопросы о бизнесе — здесь','Разберёмся вместе.','Помощник видит цифры кофейни и объясняет, что за ними стоит.','none')+`<div class="chat-layout"><section class="card chat-card"><div class="chat-top"><div><div class="assistant-heading"><span class="ai-badge">${icon('spark')}</span>Ваш Ритм</div><p>${aiConfigured?providerName():'Данные доступны · модель ещё не подключена'}</p></div><button class="tag ${aiConfigured?'green':''}" data-action="ai-settings">${aiConfigured?providerName():'Настроить ИИ'} →</button></div><div class="messages" id="messages" aria-live="polite" aria-label="Переписка с помощником">${chatMessages.length?chatMessages.map(messageHTML).join(''):messageHTML({role:'assistant',content:`Привет! Давайте посмотрим, как чувствует себя кофейня. ${d.gap?`В прогнозе есть риск: максимальная нехватка — ${money(d.gap)}.`:'В выбранном сценарии кассового разрыва нет.'} Могу объяснить расчёт, разобрать расходы или составить план. Выберите вопрос справа или напишите свой. Сейчас ${aiConfigured?'доступна подключённая модель.':'доступен разбор по правилам; свободный диалог появится после настройки модели.'}`,mode:'rules'})}</div><form class="chat-form" id="chat-form"><textarea id="chat-input" rows="1" maxlength="2000" placeholder="Например: как избежать кассового разрыва?" aria-label="Ваш вопрос" required></textarea><button class="send-btn" type="submit" aria-label="Отправить сообщение" ${busy?'disabled':''}>${icon('arrow')}</button></form></section><aside class="chat-side"><article class="card"><h3>Спросите у Ритма</h3><div class="prompt-list">${['Как избежать кассового разрыва?','Какие расходы влияют на прибыль?','Как учитывать налоги и сроки?','Составь план действий на неделю'].map(q=>`<button class="prompt-btn" data-ask="${q}" ${busy?'disabled':''}>${q}${icon('arrow')}</button>`).join('')}</div></article><article class="card" style="margin-top:18px"><h3>Контекст кофейни</h3><div class="context-row"><span>Остаток сейчас</span><strong>${money(available())}</strong></div><div class="context-row"><span>Обязательства</span><strong>${state.payments.filter(p=>!p.paid).length} платежа</strong></div><div class="context-row"><span>Горизонт прогноза</span><strong>14 дней</strong></div></article></aside></div>`}
function about(){return head('Ритм для вашего бизнеса','Больше ясности.<br>Меньше рутины.','Финансы, обязательства и помощник в одном рабочем пространстве.','none')+`<div class="feature-grid"><article class="card"><span>01 / Контроль</span><h3>Понимайте остаток</h3><p>Учитывайте выручку и расходы, сверяйте остаток и держите ближайшие платежи перед глазами.</p></article><article class="card"><span>02 / Планирование</span><h3>Видите риск заранее</h3><p>Настройте поступления и расходы. Сравнивайте прогноз на 14 дней и находите причину возможной нехватки денег.</p></article><article class="card"><span>03 / Решения</span><h3>Обсуждайте свои цифры</h3><p>Помощник объяснит показатели, разберёт расходы и предложит следующие шаги с учётом вашего плана.</p></article></div><article class="card"><h2>Ваши данные — удобным способом</h2><p style="margin-top:14px">Вносите выручку и расходы вручную, импортируйте CSV или подключите выписку через Alfa API. Для помощника доступны ChatGPT, локальная модель Ollama и совместимые API.</p><div class="heading-actions" style="margin-top:20px"><button class="btn primary" data-finance="revenue">Внести выручку</button><button class="btn secondary" data-business="bank">Подключить счёт</button></div><p class="small-caption">Ритм — независимый сервис. Подключение банка доступно владельцу счёта и не даёт Ритму права отправлять платежи.</p></article><div class="toolbar" style="margin-top:26px"><p class="small-caption">Удалить свои изменения и вернуть исходные значения.</p><button class="btn secondary" data-action="reset">Восстановить исходные данные</button></div>`}

function render(){const d=M.dashboard(state,period,uplift);const content={pulse:()=>pulse(d),analytics:()=>analytics(d),payments,assistant:()=>assistant(d),about};$('#page-content').innerHTML=`<div class="page-enter">${(content[page]||content.pulse)()}</div>`;document.querySelectorAll('.nav a').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=({pulse:'Пульс бизнеса',analytics:'Аналитика',payments:'Расходы и платежи',assistant:'AI-помощник',about:'О сервисе'}[page]||'Пульс бизнеса')+' — Ритм';$('#runtime-mode').dataset.runtime=online?'go':'browser';$('#runtime-mode').textContent=online?'Изменения сохраняются':'Данные в браузере';if(page==='assistant')scrollChat()}
function navigate(p){if(!['pulse','analytics','payments','assistant','about'].includes(p))p='pulse';if(page===p){render();return}location.hash=p}
function scrollChat(){const m=$('#messages');if(m)m.scrollTop=m.scrollHeight}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close()}
function expenseModal(){modal('Добавить расход',`<p>Расход уменьшит расчётный баланс и обновит прогноз. Учитывайте уже совершённую операцию.</p><form id="expense-form"><div class="field"><label for="expense-name">За что заплатили</label><input id="expense-name" name="name" maxlength="100" placeholder="Например, упаковка для кофе" required></div><div class="field-row"><div class="field"><label for="expense-amount">Сумма, ₽</label><input id="expense-amount" name="amount" type="number" min="1" max="100000000" step="1" placeholder="5000" required></div><div class="field"><label for="expense-category">Категория</label><select id="expense-category" name="category">${['Закупки','Команда','Аренда','Налоги','Маркетинг','Прочее'].map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="field"><label for="expense-date">Дата операции</label><input id="expense-date" name="date" type="date" value="${M.DATE}" min="2025-10-27" max="${M.DATE}" required></div><div class="field-error" id="expense-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn soft" data-action="close">Отмена</button><button type="submit" class="btn primary">Добавить расход</button></div></form>`)}
function bankModal(){modal('Подключить данные бизнеса',`<p>Подключите банковскую выписку или загрузите расходы. Подключение к реальному банку требует отдельного доступа к API.</p><div class="connect-option"><span class="ai-badge">${icon('wallet')}</span><div><strong>Данные кофейни</strong><p>Текущие расходы и финансовый план</p></div><button class="btn soft" data-action="demo-bank">Выбрать</button></div><div class="connect-option"><span class="ai-badge">${icon('down')}</span><div><strong>Импорт расходов CSV</strong><p>Загрузка в ваш локальный Go-сервер</p></div><button class="btn soft" data-action="import">Загрузить</button></div><div class="connect-option"><span class="ai-badge">${icon('link')}</span><div><strong>Альфа-Банк API</strong><p>Чтение выписки по ключу или токену</p></div><button class="btn soft" data-action="bank-api">Подключить</button></div><p class="inline-note">Ритм не запрашивает логин, пароль или код из СМС банка.</p>`)}
function settingsModal(){connectionSettings()}
function importModal(){if(!online){modal('Импорт в полной версии',`<p>Загрузка ваших расходов доступна в локальной версии с Go-сервером. В веб-версии используются только примерные данные.</p><button class="btn primary full" data-action="close">Понятно</button>`);return}modal('Загрузить расходы CSV',`<p>Формат: UTF-8, разделитель «;», целые суммы в рублях. Для расходов сумма отрицательная. Импорт добавляет записи к текущему сценарию, не заменяя выручку.</p><pre class="code-snippet">date;name;category;amount\n2026-10-27;Упаковка;Закупки;-3500</pre><form id="import-form"><div class="field"><label for="csv-file">CSV-файл до 50 КБ</label><input type="file" id="csv-file" accept=".csv,text/csv" required></div><div class="field-error" id="import-error" role="alert"></div><button class="btn primary full" type="submit">Импортировать расходы</button></form>`)}
async function ask(q){if(busy)return;q=q.trim();if(!q)return;if(q.length>2000){notify('Вопрос слишком длинный');return}const prior=chatMessages.filter(m=>m.mode!=='error').slice(-12).map(({role,content})=>({role,content}));chatMessages.push({role:'user',content:q});busy=true;if(page!=='assistant'){page='assistant';history.replaceState(null,'','#assistant')}render();const pending=document.createElement('div');pending.className='small-caption';pending.id='pending-message';pending.setAttribute('role','status');pending.textContent=aiConfigured?'Ритм изучает контекст…':'Ритм разбирает данные…';$('#messages').append(pending);scrollChat();try{const result=online?await post('/api/chat',{message:q,history:prior,period,uplift}):{answer:M.answer(q,M.dashboard(state,period,uplift),state),mode:'rules'};chatMessages.push({role:'assistant',content:result.answer,mode:result.mode})}catch(e){chatMessages.push({role:'assistant',content:e.message,mode:'error'})}finally{busy=false;if(page==='assistant')render()}}
function csvQuote(s){s=String(s);if(/^[\s]*[=+@-]/.test(s)&&!/^-[0-9]+$/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function downloadCSV(){if(online){const a=document.createElement('a');a.href='/api/report.csv?period='+period;a.download='ritm-report.csv';a.click();return}const rows=[['date','name','category','amount']];for(const h of M.history(period)){rows.push([h.date,'Выручка минус возвраты','Выручка',h.revenue-h.refunds]);rows.push([h.date,'Операционные расходы','Расходы',-h.expenses])}for(const e of state.expenses)rows.push([e.date,e.name,e.category,-e.amount]);const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvQuote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ritm-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-go],[data-action],[data-period],[data-uplift],[data-pay],[data-advice],[data-ask]');if(!b)return;if(b.dataset.go){navigate(b.dataset.go);return}if(b.dataset.ask){if($('#modal').open)closeModal();ask(b.dataset.ask);return}if(b.dataset.period){period=Number(b.dataset.period);render();return}if(b.dataset.uplift!==undefined){uplift=Number(b.dataset.uplift);render();return}if(b.dataset.pay){const p=state.payments.find(p=>p.id===b.dataset.pay);if(!p)return;modal('Учесть оплату',`<p>Отметить «${esc(p.name)}» на сумму <b>${money(p.amount)}</b> как уже оплаченное обязательство?</p><p>Остаток уменьшится, а обязательство исчезнет из будущих платежей. Ритм не отправляет деньги.</p><div class="modal-actions"><button class="btn soft" data-action="close">Отмена</button><button class="btn primary" data-action="confirm-pay" data-id="${p.id}">Учесть в учёте</button></div>`);return}if(b.dataset.advice){b.disabled=true;try{if(online)await post('/api/advice/'+b.dataset.advice+'/toggle');else if(state.done.includes(b.dataset.advice))state.done=state.done.filter(v=>v!==b.dataset.advice);else state.done.push(b.dataset.advice);await sync();render()}catch(err){notify(err.message);b.disabled=false}return}const action=b.dataset.action;if(action==='close')closeModal();if(action==='expense')expenseModal();if(action==='export')downloadCSV();if(action==='import'){if($('#modal').open)closeModal();importModal()}if(action==='ai-settings')settingsModal();if(action==='demo-bank'){closeModal();notify('Выбран сценарий кофейни. Реальный банк не подключён.')}if(action==='bank-api')bankAPIModal();if(action==='score')scoreModal();if(action==='table'){const d=M.dashboard(state,period,uplift);modal('Показатели по дням',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Дата</th><th>Выручка</th><th>Покупок</th><th>Чек</th></tr></thead><tbody>${d.history.map(h=>`<tr><td>${date(h.date)}</td><td>${money(h.revenue-h.refunds)}</td><td>${h.orders}</td><td>${money(h.orders?Math.floor((h.revenue-h.refunds)/h.orders):0)}</td></tr>`).join('')}</tbody></table></div>`)}if(action==='confirm-pay'){b.disabled=true;const before=M.dashboard(state,period,0).score;try{if(online)await post('/api/payments/'+b.dataset.id+'/pay');else state.payments.find(p=>p.id===b.dataset.id).paid=true;await sync();closeModal();render();notifyScore('Оплата учтена',before)}catch(err){notify(err.message);b.disabled=false}}if(action==='reset')modal('Вернуть исходный сценарий',`<p>Добавленные расходы и отметки оплаты будут удалены. Исходный сценарий кофейни восстановится.</p><div class="modal-actions"><button class="btn soft" data-action="close">Отмена</button><button class="btn primary" data-action="confirm-reset">Восстановить исходные данные</button></div>`);if(action==='confirm-reset'){b.disabled=true;try{if(online)state=await post('/api/reset');else{state=M.initial();saveLocal()}chatMessages=[];uplift=0;closeModal();render();notify('Исходные данные восстановлены')}catch(err){notify(err.message);b.disabled=false}}});
document.addEventListener('submit',async e=>{if(e.target.id==='chat-form'){e.preventDefault();const input=$('#chat-input');const q=input.value;input.value='';ask(q)}if(e.target.id==='expense-form'){e.preventDefault();const f=e.target,button=f.querySelector('[type=submit]'),data=Object.fromEntries(new FormData(f));data.amount=Number(data.amount);data.name=data.name.trim();if(/[<>\r\n\t]/.test(data.name)){$('#expense-error').textContent='Введите обычное название без HTML и переносов строк.';return}if(!data.name||!Number.isInteger(data.amount)||data.amount<=0||data.amount>100000000){$('#expense-error').textContent='Укажите название и целую положительную сумму.';return}button.disabled=true;try{if(online)await post('/api/expenses',data);else{state.expenses.push({...data,id:crypto.randomUUID()});saveLocal()}await sync();closeModal();render();notify('Расход добавлен. Баланс и прогноз обновлены.')}catch(err){$('#expense-error').textContent=err.message;button.disabled=false}}if(e.target.id==='import-form'){e.preventDefault();const f=$('#csv-file').files[0];if(!f)return;if(f.size>50000){$('#import-error').textContent='Файл больше 50 КБ';return}const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const r=await post('/api/import',{csv:await f.text()});await sync();importedCount+=r.imported;closeModal();render();notify(`Импортировано расходов: ${r.imported}`)}catch(err){$('#import-error').textContent=err.message;button.disabled=false}}});
document.addEventListener('input',e=>{if(e.target.id==='expense-search'){operationFilter=e.target.value;$('#expense-table').innerHTML=expensesTable()}});
document.addEventListener('submit',async e=>{if(e.target.id!=='ai-config-form')return;e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;button.textContent='Проверяем подключение…';const data=Object.fromEntries(new FormData(e.target));try{await post('/api/ai/config',data);aiConfigured=true;aiProvider='api';$('#ai-key').value='';closeModal();render();notify('Модель ответила. AI-помощник подключён.')}catch(err){$('#ai-error').textContent=err.message;button.disabled=false;button.textContent='Подключить и проверить'}finally{data.key=''}});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit()}});
$('#close-modal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});$('#connect-bank').addEventListener('click',bankModal);
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'pulse';if(!['pulse','analytics','payments','assistant','about'].includes(page))page='pulse';render();window.scrollTo({top:0,behavior:'instant'})});
async function init(){try{const h=await api('/api/health');if(h.status==='ok'&&h.storage==='go-file'){online=true;aiConfigured=h.aiConfigured;aiProvider=h.provider||'';state=await api('/api/state')}}catch{try{const saved=JSON.parse(localStorage.getItem('ritm-state-v1'));if(saved?.version===2&&Array.isArray(saved.expenses)&&Array.isArray(saved.payments)&&Array.isArray(saved.done))state=saved}catch{}}page=location.hash.slice(1)||'pulse';if(!['pulse','analytics','payments','assistant','about'].includes(page))page='pulse';render();initConnection();initBusiness()}
init();
